uniform float uTime;
uniform sampler2D uEdge;
uniform sampler2D uCloud;
uniform vec3 uFogCol;
uniform vec3 uLightDir;
uniform float uAmp;
uniform float uFreq;
uniform float uSeed;
uniform float uDrift;
uniform float uK;
uniform float uFlip;
uniform float uOpacity;
uniform float uWarm;
uniform float uFade;
uniform float uRag;
uniform float uFarK;
uniform float uSoftK;
uniform float uFloorY;
uniform float uFogTone;
uniform float uFogDim;
uniform float uFogLit;
uniform float uFogDeep;
varying vec3 vW;
varying float vTop;
void main() {
  float s = uFlip > 0.5 ? -1.0 : 1.0;
  float top0 = vTop;
  float wx = vW.x + uTime * uDrift;

  float warp = texture2D(uCloud, vec2(wx * uFreq * 0.31 + uSeed, (vW.y - top0) * 0.012 + uSeed * 3.0)).r - 0.5;
  float x = wx * uFreq + uSeed + warp * 0.09 * (uFlip > 0.5 ? 0.2 : 1.0);

  float e = texture2D(uEdge, vec2(x, 0.5), uFlip > 0.5 ? 3.0 : 2.0 * log2(uSoftK)).r;

  vec2 q = vec2(wx, (vW.y - top0) * 1.7) / max(uAmp, 0.5);
  float n1 = texture2D(uCloud, q * 0.17 + vec2(uSeed, uTime * 0.004)).r - 0.5;
  float n2 = texture2D(uCloud, q * 0.61 + vec2(-uTime * 0.007, uSeed * 2.0)).r - 0.5;
  float top = top0 + s * (e * uAmp + (n1 * 0.55 + n2 * 0.22 / uSoftK) * uAmp * uRag);
  float d = (top - vW.y) * s;
  float soft = (uAmp * (0.09 + 0.34 * clamp(n1 + 0.5, 0.0, 1.0)) + 0.03) * uSoftK;
  float a = smoothstep(0.0, soft, d) * smoothstep(uFloorY, uFloorY + 6.0, vW.y);
  if (a < 0.004) discard;

  float eL = texture2D(uEdge, vec2(x, 0.5), 5.5).r;
  float dL = (top0 + s * eL * uAmp - vW.y) * s;
  vec3 Vw = vW - cameraPosition;
  vec3 V = toSky(normalize(Vw));
