  return 4.8 + 1.65 * smoothstep(24.0, 28.6, x) - 0.3 * left * left + 0.26 * sin(x * 1.55 + 0.4) + 0.15 * sin(x * 3.7 + 2.2) + 0.06 * sin(x * 8.9 + 1.0);
}

float sqJamb(float y) { float u = y / 0.85, k = floor(u); return mix(sqJambS(k * 0.85), sqJambS((k + 1.0) * 0.85), fract(u)); }
float sqTop(float x) { float u = (x - 0.3) / 0.7, k = floor(u); return mix(sqTopS(k * 0.7 + 0.3), sqTopS((k + 1.0) * 0.7 + 0.3), fract(u)); }
float sqOpen(vec2 p) { return min(p.x - sqJamb(p.y), sqTop(p.x) - p.y); }

float sqEdge(float y) { return 0.42 * sin(y * 0.83 + 0.5) + 0.24 * sin(y * 2.1 + 1.7) + 0.1 * sin(y * 5.3); }

vec3 sqRim(vec3 col, vec2 p, float d, float k, vec3 lit) {
  float t = -d;
  float s = (p.x - p.y * 0.55) / 1.3 + 0.35 * sin(p.y * 0.9 + p.x * 0.4);
  float fs = fract(s), h = fract(sin(floor(s) * 127.1) * 43758.5453);

  float w = 0.14 + 0.16 * h;
  float seam = step(0.08, fs) * (1.0 - step(0.94, fs));
  float band = (1.0 - smoothstep(w - 0.015, w + 0.015, t)) * smoothstep(0.0, 0.02, t) * seam;
  float moon = mix(0.6, 1.15, (1.0 - smoothstep(23.5, 30.0, p.x))) * mix(0.85, 1.1, smoothstep(1.0, 5.0, p.y));
  float topE = step(sqTop(p.x) - p.y, p.x - sqJamb(p.y));
  return mix(col, lit * (0.9 + 0.3 * h), clamp(band * moon * k * mix(1.0, 0.45, topE), 0.0, 1.0));
}

look_m_:
float rtLum(vec3 c) { return dot(c, vec3(0.3, 0.55, 0.15)); }

float rtBase(float z) { float sk = rtLum(uMid); return (1.5 * rtLum(layerColor(min(z + 2.0, 0.0))) + 0.0415 * sk + 0.055 * (1.0 - smoothstep(0.0, 0.15, sk))) * 1.00; }

vec3 rtTint() { vec3 s = mix(uMid, uHorizon, 0.08); return mix(s / max(rtLum(s), 1e-4), vec3(0.92, 0.97, 1.2), uGlowSoft); }

float rtFall(float z) { return mix(1.0, mix(0.74, 0.62, uGlowSoft), smoothstep(-1.7, 2.2, z)) * mix(1.0, 0.50, smoothstep(2.2, 9.0, z)); }
vec3 rtKeyDir(vec3 W) { return normalize(vec3(uSunAnchor.x, uSunAnchor.y + 3.5, max(4.5, W.z + 3.5)) - W); }

vec3 roadTone(vec3 N, vec3 W) { return rtTint() * rtBase(W.z) * mix(0.74, 1.12, smoothstep(0.1, 0.6, dot(N, rtKeyDir(W)))) * rtFall(W.z); }

vec3 roadRim(vec3 W) {
  float w = texture2D(uNoise, W.xz * vec2(0.09, 0.05)).g - 0.5;
  float r = smoothstep(-2.3, -1.5, W.z + w * 0.5) * (1.0 - smoothstep(-1.2, -0.3, W.z + w * 0.9));

  return rtTint() * rtBase(W.z) * mix(0.15, 1.0, uGlowSoft) * 0.35 * r * smoothstep(0.35, 0.6, texture2D(uNoise, vec2(W.x * 0.04, 0.3)).r);
}

vec3 roadLamp(vec3 ffl, vec3 W, vec3 N, float k) {
  vec3 Lp = uGlowPos[0].xyz - W;
  float d = length(Lp), R = max(uGlowPos[0].w, 1e-3);
  float gt = max(1.0 - d / R, 0.0);
  vec3 h0 = uGlowCol[0] * mix(smoothstep(0.0, 1.0, clamp((R - d) / (R * 0.55), 0.0, 1.0)), gt * gt * gt, uGlowSoft) * (0.3 + 0.7 * max(dot(N, Lp / max(d, 1e-3)), 0.0));
  float t = max(1.0 - length(Lp.xz) / 3.00, 0.0);
  return ffl + h0 * k * uGlowSoft * (0.34 * t * t - 1.0);
}

uniform sampler2D uSqShadow;
uniform vec4 uSqBox;
uniform vec2 uSqSlope;
uniform float uSqOx;
float sqShadow(vec3 P, float warp) {
  vec2 p = P.xz + P.y * uSqSlope + vec2(warp * 0.5, warp);
  vec2 uv = (p - uSqBox.xy) * uSqBox.zw;
  if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return 0.0;
  return texture2D(uSqShadow, uv).r;
}

vec3 sqKey(vec3 W) { return normalize(vec3(uSunAnchor.x, uSunAnchor.y + 3.5, max(4.5, W.z + 3.5)) - W); }

vec3 sqRamp(vec3 N, vec3 W) {
  float lx = W.x - uSqOx;
  float nl = dot(N, sqKey(W));
  vec3 P = vec3(lx, W.y, W.z);
  float sh = 1.0 - sqShadow(P, 0.0) * 0.1;
  sh = 1.0 - sqShadow(P, 0.0) * mix(0.1, 0.5, (1.0 - smoothstep(-2.4, -1.0, W.z)));


  vec3 Nr = normalize(mix(N, vec3(0.0, 1.0, 0.0), smoothstep(1.3, 1.8, W.z) * (1.0 - smoothstep(2.9, 3.8, W.z)) * smoothstep(21.0, 24.0, lx)));
  vec3 c = roadTone(Nr, W) * sh;
  c *= mix(1.0, 0.86, smoothstep(3.0, 13.0, W.z));
  c *= 0.74;
  c += vec3(0.0058, 0.0066, 0.0098) * smoothstep(2.2, 9.0, W.z);
  c *= 1.0 - 0.55 * smoothstep(25.0, 31.0, lx);
  c = mix(c, vec3(0.0060, 0.0070, 0.0116), smoothstep(28.0, 30.8, lx));
  float sunD = (lx - 18.5) / 9.0;
  c += 0.07 * roadRim(W) * sh * mix(0.6, 1.2, exp(-sunD * sunD)) * (1.0 - smoothstep(24.2, 26.5, lx));
  return c;
}

float sqK(vec3 W) {
  float lx = W.x - uSqOx;
  return smoothstep(-6.6, -6.0, W.z) * smoothstep(-16.0, 4.0, lx) * (1.0 - smoothstep(30.5, 33.5, lx));
}

float sqLampK(vec3 W) { return clamp(sqK(W) * 4.0, 0.0, 1.0); }
vec3 sqGround(vec3 N, vec3 W, vec3 old) {
  return mix(old, sqRamp(N, W), sqK(W));
}

