    float band = exp(-bz * bz) * smoothstep(0.2, 0.75, azB);
    float brk = 0.75 + 0.25 * texture2D(uNoise, vec2(P.x * 0.09 + uTime * 0.004, P.z * 0.6)).g;
    col += uLightCol * band * brk * 0.075 * uLightAmt * rvN;
