  col = mix(col, uFogCol, clamp((uFog.x * 0.35 + 0.28) * smoothstep(14.0, 62.0, d), 0.0, 0.72) * (1.0 - 0.5 * w5k) * mix(1.0, 0.45, rvN));
  return col;
}

